#!/usr/bin/env python3
"""Fail when the version numbers in this repository disagree.

The version is written down in more than one place and every copy has a
different consumer:

* ``src/novel_downloader/__init__.py`` -- the package, the PyInstaller version
  resources, ``doctor`` and the update manifest all read it;
* ``android/app/build.gradle.kts`` -- the APK's ``versionName`` is a
  hand-maintained copy that no Python build can patch;
* ``pyproject.toml`` -- must derive the version from the package instead of
  pinning a second literal;
* ``latest.json`` -- generated by ``scripts/release.py`` from the package
  version; a local release directory that exists for the *current* version is
  also checked when present.

A drift here ships an APK that reports a different version than the desktop
update manifest offers, which silently disables Android updates.  This script
is the cheap, dependency-free gate for that; CI runs it on every push.

Usage::

    python scripts/check_versions.py
    python scripts/check_versions.py --root . --json
"""

from __future__ import annotations

import argparse
import importlib.util
import json
import re
import sys
import tomllib
from dataclasses import dataclass
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]

_VERSION_RE = re.compile(r'^__version__\s*=\s*["\']([^"\']+)["\']', re.MULTILINE)
_GRADLE_VERSION_NAME_RE = re.compile(r'versionName\s*=\s*"([^"]+)"')
_GRADLE_VERSION_CODE_RE = re.compile(r"versionCode\s*=\s*(\d+)")
#: The attribute ``[tool.setuptools.dynamic]`` must point at.
EXPECTED_VERSION_ATTR = "novel_downloader.__version__"


class VersionError(RuntimeError):
    """A version source is missing or unreadable."""


@dataclass(frozen=True)
class Check:
    """One consistency check: a name, its verdict and a human-readable detail."""

    name: str
    ok: bool
    detail: str


def _pass(name: str, detail: str) -> Check:
    return Check(name=name, ok=True, detail=detail)


def _fail(name: str, detail: str) -> Check:
    return Check(name=name, ok=False, detail=detail)


def read_package_version(root: Path) -> str:
    """
    Return ``__version__`` from ``src/novel_downloader/__init__.py``.

    The file is parsed rather than imported: this gate must work without an
    editable install and must never execute package code.

    :raises VersionError: when the file or the assignment is missing.
    """
    init_py = root / "src" / "novel_downloader" / "__init__.py"
    if not init_py.is_file():
        raise VersionError(f"package version file not found: {init_py}")
    match = _VERSION_RE.search(init_py.read_text(encoding="utf-8"))
    if match is None:
        raise VersionError(f"no __version__ string in {init_py}")
    return match.group(1).strip()


def read_android_versions(root: Path) -> tuple[str, int]:
    """
    Return ``(versionName, versionCode)`` from the Gradle module file.

    :raises VersionError: when either value is missing or invalid.
    """
    gradle = root / "android" / "app" / "build.gradle.kts"
    if not gradle.is_file():
        raise VersionError(f"Android module file not found: {gradle}")
    text = gradle.read_text(encoding="utf-8")
    name_match = _GRADLE_VERSION_NAME_RE.search(text)
    if name_match is None:
        raise VersionError(f"no versionName in {gradle}")
    code_match = _GRADLE_VERSION_CODE_RE.search(text)
    if code_match is None:
        raise VersionError(f"no versionCode in {gradle}")
    code = int(code_match.group(1))
    if code <= 0:
        raise VersionError(f"versionCode must be positive in {gradle}, got {code}")
    return name_match.group(1).strip(), code


def check_package_and_android(root: Path) -> Check:
    """``__version__`` and the Android ``versionName`` must be identical."""
    name = "package/Android versionName"
    try:
        package = read_package_version(root)
        android, code = read_android_versions(root)
    except VersionError as exc:
        return _fail(name, str(exc))
    if package != android:
        return _fail(
            name,
            f"__version__ {package!r} != android versionName {android!r} "
            "(update android/app/build.gradle.kts)",
        )
    return _pass(name, f"{package} (versionCode {code})")


def check_pyproject_dynamic(root: Path) -> Check:
    """``pyproject.toml`` must derive the version, never pin a second copy."""
    name = "pyproject version source"
    pyproject = root / "pyproject.toml"
    if not pyproject.is_file():
        return _fail(name, f"file not found: {pyproject}")
    try:
        document = tomllib.loads(pyproject.read_text(encoding="utf-8"))
    except (OSError, tomllib.TOMLDecodeError) as exc:
        return _fail(name, f"cannot parse {pyproject}: {exc}")

    project = document.get("project")
    if not isinstance(project, dict):
        return _fail(name, "[project] table is missing")
    if "version" in project:
        return _fail(
            name,
            '[project] pins a static version; use dynamic = ["version"] and '
            "let setuptools read the package",
        )
    dynamic = project.get("dynamic")
    if not isinstance(dynamic, list) or "version" not in dynamic:
        return _fail(name, '[project] dynamic must contain "version"')

    tool = document.get("tool")
    setuptools = tool.get("setuptools") if isinstance(tool, dict) else None
    dynamic_table = setuptools.get("dynamic") if isinstance(setuptools, dict) else None
    entry = dynamic_table.get("version") if isinstance(dynamic_table, dict) else None
    attr = entry.get("attr") if isinstance(entry, dict) else None
    if attr != EXPECTED_VERSION_ATTR:
        return _fail(
            name,
            "[tool.setuptools.dynamic] version.attr is "
            f"{attr!r}, expected {EXPECTED_VERSION_ATTR!r}",
        )
    return _pass(name, f"dynamic version -> {EXPECTED_VERSION_ATTR}")


def _load_module(path: Path, name: str) -> Any:
    """Import a script by path without adding its directory to ``sys.path``."""
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise VersionError(f"cannot load {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    try:
        spec.loader.exec_module(module)
    except BaseException:
        sys.modules.pop(name, None)
        raise
    return module


def check_release_version_source(root: Path) -> Check:
    """``release.py`` must read the version from the package, not a literal."""
    name = "latest.json version source"
    release_py = root / "scripts" / "release.py"
    if not release_py.is_file():
        return _fail(name, f"file not found: {release_py}")
    try:
        package = read_package_version(root)
        module = _load_module(release_py, "_check_versions_release")
        release_version = str(module.read_version(root))
    except VersionError as exc:
        return _fail(name, str(exc))
    except Exception as exc:  # noqa: BLE001 - a refactor must fail the gate cleanly
        return _fail(name, f"cannot inspect {release_py}: {exc}")
    if release_version != package:
        return _fail(
            name,
            f"release.read_version() returned {release_version!r}, "
            f"package is {package!r}",
        )
    text = release_py.read_text(encoding="utf-8")
    if "read_version(" not in text or "build_manifest_document(" not in text:
        return _fail(
            name,
            "release.py no longer derives latest.json from read_version() / "
            "build_manifest_document()",
        )
    return _pass(name, f"release.py reads {package} from the package")


def check_local_latest_json(root: Path) -> Check:
    """
    Validate a locally built ``latest.json`` for the current version, if any.

    Release directories are build output and are normally absent in CI; when
    one exists for the version in the tree, its ``version``/``tag`` must match
    or the release that produced it was wrong.
    """
    name = "local latest.json"
    try:
        package = read_package_version(root)
    except VersionError as exc:
        return _fail(name, str(exc))
    pattern = f"novel-downloader-{package}-*/latest.json"
    manifests = sorted((root / "dist" / "release").glob(pattern))
    if not manifests:
        return _pass(name, f"not built for {package} (nothing to compare)")
    for manifest in manifests:
        try:
            document = json.loads(manifest.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            return _fail(name, f"cannot read {manifest}: {exc}")
        version = document.get("version") if isinstance(document, dict) else None
        tag = document.get("tag") if isinstance(document, dict) else None
        if version != package or tag != f"v{package}":
            return _fail(
                name,
                f"{manifest} says version={version!r} tag={tag!r}, "
                f"expected {package!r} / 'v{package}'",
            )
    return _pass(name, f"{len(manifests)} manifest(s) for {package}")


def run_checks(root: Path) -> list[Check]:
    """Run every consistency check against *root* (never raises for drift)."""
    return [
        check_package_and_android(root),
        check_pyproject_dynamic(root),
        check_release_version_source(root),
        check_local_latest_json(root),
    ]


def main(argv: list[str] | None = None) -> int:
    """Print the check results and return 0 only when every check passes."""
    parser = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "--root",
        type=Path,
        default=ROOT,
        help="repository root (default: the checkout containing this script)",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        dest="as_json",
        help="emit the results as JSON instead of a text report",
    )
    args = parser.parse_args(argv)

    root: Path = args.root.resolve()
    checks = run_checks(root)
    failed = [check for check in checks if not check.ok]

    if args.as_json:
        payload = {
            "root": str(root),
            "ok": not failed,
            "checks": [
                {"name": check.name, "ok": check.ok, "detail": check.detail}
                for check in checks
            ],
        }
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        for check in checks:
            status = "OK  " if check.ok else "FAIL"
            print(f"[{status}] {check.name}: {check.detail}")
        print()
        if failed:
            print(f"{len(failed)} version consistency check(s) failed.")
        else:
            print("All version sources agree.")
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())
